const s = $getWorkflowStaticData("global"),
  now = Math.floor(Date.now() / 1000);
if (s.lastChargeRun == null) s.lastChargeRun = now;
if (!Number.isSafeInteger(s.lastChargeRun) || s.lastChargeRun < 0 || s.lastChargeRun > now)
  throw Error("Invalid saved charge watermark");
return [{ json: { since: s.lastChargeRun, until: now } }];

const out = [];
for (const p of $input.all()) {
  const body = p.json.body;
  if (!body || !Array.isArray(body.data)) throw Error("Invalid Stripe page");
  for (const c of body.data) {
    if (!c || !["succeeded", "pending", "failed"].includes(c.status) || typeof c.id !== "string")
      throw Error("Invalid Stripe charge");
    if (c.status !== "succeeded") continue;
    if (
      typeof c.customer !== "string" ||
      !c.customer ||
      !Number.isSafeInteger(c.amount) ||
      typeof c.currency !== "string" ||
      !(c.description === null || typeof c.description === "string")
    )
      throw Error("Invalid charge or missing customer");
    out.push({ json: c });
  }
}
return out;

const c = $("Process charges one by one").item.json;
if (
  $json.id !== c.customer ||
  $json.deleted === true ||
  typeof $json.name !== "string" ||
  !$json.name.trim()
)
  throw Error("Charge customer has no usable name or mismatched ID");
return [{ json: { name: $json.name } }];

function chargeAmount(amount, currency) {
  const supported =
      "usd aed afn all amd ang aoa ars aud awg azn bam bbd bdt bif bhd bmd bnd bob brl bsd bwp byn bzd cad cdf chf clp cny cop crc cve czk djf dkk dop dzd egp etb eur fjd fkp gbp gel gip gmd gnf gtq gyd hkd hnl htg huf idr ils inr isk jmd jod jpy kes kgs khr kmf krw kwd kyd kzt lak lbp lkr lrd lsl mad mdl mga mkd mmk mnt mop mur mvr mwk mxn myr mzn nad ngn nio nok npr nzd omr pab pen pgk php pkr pln pyg qar ron rsd rub rwf sar sbd scr sek sgd shp sle sos srd std szl thb tjs tnd top try ttd twd tzs uah ugx uyu uzs vnd vuv wst xaf xcd xcg xof xpf yer zar zmw".split(
        " ",
      ),
    zero = "bif clp djf gnf jpy kmf krw mga pyg rwf vnd vuv xaf xof xpf".split(" ");
  if (
    !Number.isSafeInteger(amount) ||
    amount < 0 ||
    typeof currency !== "string" ||
    !supported.includes(currency)
  )
    throw Error("Unsupported or invalid Stripe charge currency or amount");
  if ((currency === "isk" || currency === "ugx") && amount % 100 !== 0)
    throw Error("Invalid Stripe special-currency amount");
  if (zero.includes(currency)) return String(amount);
  const places = ["bhd", "jod", "kwd", "omr", "tnd"].includes(currency) ? 3 : 2,
    digits = String(amount).padStart(places + 1, "0");
  return digits.slice(0, -places) + "." + digits.slice(-places);
}

const a = $input.all();
if (a.length !== 1 || !Number.isSafeInteger(a[0].json.id) || a[0].json.id < 1)
  throw Error("Expected one exact organization match");
const c = $("Process charges one by one").item.json,
  esc = (x) =>
    String(x ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#39;");
return [
  {
    json: {
      orgId: a[0].json.id,
      content:
        esc(c.description) + ": " + chargeAmount(c.amount, c.currency) + " " + esc(c.currency),
    },
  },
];

if ($input.all().length !== 1 || !Number.isSafeInteger($json.id) || $json.id < 1)
  throw Error("Pipedrive did not confirm note");
return $input.all();

const s = $getWorkflowStaticData("global"),
  until = $("Read the last run time").first().json.until;
if (!Number.isSafeInteger(until)) throw Error("Invalid run time");
s.lastChargeRun = until;
return $input.all();
